// ===== share.js =====
/**
 * Compact shareable configuration links: ?c=<base64url>.
 * Schema versioned; prices never embedded (re-fetched on open).
 */

/** Bump when field layout / meaning changes incompatibly. */
const SHARE_SCHEMA_VERSION = 1;

const PTYPE = ["apartment", "house", "townhouse", "commercial"];
const STAGE = ["design", "construction", "renovation", "existing"];
const BOILER = ["none", "opentherm", "relay"];
const HA = ["needed", "own"];
const TEMP = ["none", "DS18B20", "PT100", "PT1000"];

/** Room numeric/select fields → 1–2 letter keys (omit zeros / defaults). */
const ROOM_KEYS = [
  ["lo", "lights_onoff", 0],
  ["ld", "lights_dimmable", 0],
  ["ls", "led_strips", 0],
  ["lc", "led_strip_channels", 4],
  ["l1", "led_single", 0],
  ["sw", "switches", 0],
  ["sh", "shutters", 0],
  ["uf", "ufh_loops", 0],
  ["ue", "ufh_electric", 0],
  ["l0", "lights_0_10v", 0],
  ["ts", "temp_sensor", "none"],
  ["lk", "leak_sensors", 0],
  ["mo", "motion_sensors", 0],
  ["pr", "presence_sensors", 0],
  ["dc", "door_contacts", 0],
  ["ss", "smart_sockets", 0],
  ["ef", "extract_fan", 0],
];

const SYS_SECTIONS = {
  h: "heating",
  v: "ventilation",
  w: "water",
  e: "electrical",
  s: "security",
  l: "lighting_scenes",
};

const HEATING_KEYS = [
  ["b", "boiler", "none"],
  ["c", "collector_loops", 0],
  ["p", "heating_pumps", 0],
  ["f", "fan_coils", 0],
  ["hp", "heat_pump", 0],
  ["fp", "fireplace", 0],
  ["pt", "pt100_sensors", 0],
  ["ds", "ds18b20_sensors", 0],
];
const VENT_KEYS = [
  ["a", "ahu", 0],
  ["r", "recuperator", 0],
  ["x", "extract_fans", 0],
  ["d", "dampers_0_10v", 0],
  ["s0", "sensors_0_10v", 0],
  ["s4", "sensors_4_20ma", 0],
];
const WATER_KEYS = [
  ["lz", "leak_zones", 0],
  ["sv", "shutoff_valves", 0],
  ["wm", "water_meters", 0],
  ["ir", "irrigation", 0],
  ["wp", "water_pumps", 0],
  ["dh", "dhw_recirc", 0],
  ["gv", "gas_valve", 0],
];
const ELEC_KEYS = [
  ["ep", "energy_phases", 0],
  ["ls", "load_shed", 0],
  ["ev", "ev_chargers", 0],
  ["pv", "pv_inverters", 0],
  ["fc", "fault_contacts", 0],
];
const SEC_KEYS = [
  ["dc", "dry_contacts", 0],
  ["g", "gates", 0],
  ["lk", "locks", 0],
  ["pb", "panic_buttons", 0],
];
const LIGHT_KEYS = [
  ["st", "stair_steps", 0],
  ["az", "accent_zones", 0],
  ["gl", "garden_lights", 0],
];

const SECTION_KEYS = {
  heating: HEATING_KEYS,
  ventilation: VENT_KEYS,
  water: WATER_KEYS,
  electrical: ELEC_KEYS,
  security: SEC_KEYS,
  lighting_scenes: LIGHT_KEYS,
};

function idxOf(list, val, fallback = 0) {
  const i = list.indexOf(val);
  return i >= 0 ? i : fallback;
}

function fromIdx(list, i, fallback) {
  return list[i] ?? fallback;
}

function packSparse(obj, keys) {
  const out = {};
  for (const [short, long, def] of keys) {
    const v = obj?.[long];
    if (v == null || v === def) continue;
    if (typeof def === "number" && !(Number(v) > 0) && Number(def) === 0) continue;
    out[short] = typeof def === "number" ? Number(v) || 0 : v;
  }
  return Object.keys(out).length ? out : null;
}

function unpackSparse(packed, keys, target) {
  if (!packed || typeof packed !== "object") return target;
  for (const [short, long, def] of keys) {
    if (Object.prototype.hasOwnProperty.call(packed, short)) {
      target[long] = typeof def === "number" ? Number(packed[short]) || 0 : packed[short];
    }
  }
  return target;
}

function bytesToBase64Url(bytes) {
  let bin = "";
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  const b64 =
    typeof btoa === "function"
      ? btoa(bin)
      : Buffer.from(bytes).toString("base64");
  return b64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function base64UrlToBytes(s) {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((s.length + 3) % 4);
  if (typeof atob === "function") {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  return new Uint8Array(Buffer.from(b64, "base64"));
}

function utf8Encode(str) {
  if (typeof TextEncoder !== "undefined") return new TextEncoder().encode(str);
  return Buffer.from(str, "utf8");
}

function utf8Decode(bytes) {
  if (typeof TextDecoder !== "undefined") return new TextDecoder().decode(bytes);
  return Buffer.from(bytes).toString("utf8");
}

/**
 * Build a minimal share payload from live configurator state.
 * @param {object} state
 */
function buildSharePayload(state) {
  const panels = Array.isArray(state.panels) && state.panels.length
    ? state.panels
    : [{ id: "panel-1", name: "Main panel", location: "" }];
  const panelIds = panels.map((p) => p.id);

  const payload = { v: SHARE_SCHEMA_VERSION };

  if (state.ui_mode === "simple") payload.m = "s";
  if (state.expert) payload.x = 1;

  const o = state.object || {};
  const oPacked = [];
  oPacked.push(idxOf(PTYPE, o.property_type, 0));
  oPacked.push(Number(o.floor_area_m2) || 0);
  oPacked.push(Number(o.floors) || 1);
  oPacked.push(idxOf(STAGE, o.stage, 0));
  if (o.name) oPacked.push(String(o.name));
  payload.o = oPacked;

  const needPanels =
    panels.length !== 1 ||
    panels[0].id !== "panel-1" ||
    (panels[0].name && panels[0].name !== "Main panel") ||
    panels[0].location;
  if (needPanels) {
    payload.p = panels.map((p) => {
      const row = [p.id || "panel-1"];
      if (p.name && p.name !== "Main panel") row.push(p.name);
      else row.push("");
      if (p.location) row.push(p.location);
      return row;
    });
  }

  if (!state.expert) {
    const rooms = Array.isArray(state.rooms) ? state.rooms.filter((r) => r?.name?.trim()) : [];
    payload.r = rooms.map((r) => {
      const pIdx = Math.max(0, panelIds.indexOf(r.panel_id || panelIds[0]));
      const sparse = {};
      for (const [short, long, def] of ROOM_KEYS) {
        let v = r[long];
        if (long === "temp_sensor") {
          if (!v || v === def) continue;
          sparse[short] = idxOf(TEMP, v, 0);
          continue;
        }
        if (long === "led_strip_channels") {
          const n = Number(v) || 4;
          if (n === 4) continue;
          sparse[short] = n;
          continue;
        }
        const n = Number(v) || 0;
        if (n === def || n === 0) continue;
        sparse[short] = n;
      }
      if (r.manual && typeof r.manual === "object" && Object.keys(r.manual).length) {
        sparse.m = 1;
      }
      const row = [r.template || "living", r.name.trim(), pIdx];
      if (Object.keys(sparse).length) row.push(sparse);
      return row;
    });

    const y = {};
    for (const [short, long] of Object.entries(SYS_SECTIONS)) {
      const sec = state.systems?.[long] || {};
      const keys = SECTION_KEYS[long];
      const packed = packSparse(sec, keys);
      const out = packed ? { ...packed } : {};
      if (long === "heating" && sec.boiler && sec.boiler !== "none") {
        out.b = idxOf(BOILER, sec.boiler, 0);
      }
      if (long === "security" && Array.isArray(sec.powered_sensors) && sec.powered_sensors.length) {
        out.ps = sec.powered_sensors
          .filter((row) => (Number(row.qty) || 0) > 0)
          .map((row) => [row.type || "pir", Number(row.qty) || 0]);
        if (!out.ps.length) delete out.ps;
      }
      const pIdx = Math.max(0, panelIds.indexOf(sec.panel_id || panelIds[0]));
      if (pIdx > 0) out.pi = pIdx;
      if (Object.keys(out).length) y[short] = out;
    }
    const sys = state.systems?.system || {};
    const g = {};
    if (sys.manual_control === false) g.m = 0;
    if (sys.ha_server && sys.ha_server !== "needed") g.h = idxOf(HA, sys.ha_server, 0);
    if (Object.keys(g).length) y.g = g;
    if (Object.keys(y).length) payload.y = y;
  } else if (state.expertDemand && typeof state.expertDemand === "object") {
    payload.d = state.expertDemand;
  }

  return payload;
}

/**
 * @param {object} payload
 * @returns {{ patch: object, older: boolean, ok: boolean, error?: string }}
 */
function expandSharePayload(payload) {
  if (!payload || typeof payload !== "object") {
    return { patch: null, older: false, ok: false, error: "empty" };
  }
  const ver = Number(payload.v) || 0;
  const older = ver > 0 && ver < SHARE_SCHEMA_VERSION;
  const newer = ver > SHARE_SCHEMA_VERSION;
  // Newer schema: still try known keys; flag as older-message (settings may differ).
  const warn = older || newer || ver === 0;

  const panels = Array.isArray(payload.p) && payload.p.length
    ? payload.p.map((row, i) => ({
        id: String(row[0] || `panel-${i + 1}`),
        name: String(row[1] || (i === 0 ? "Main panel" : `Panel ${i + 1}`)),
        location: String(row[2] || ""),
      }))
    : [{ id: "panel-1", name: "Main panel", location: "" }];
  const panelIds = panels.map((p) => p.id);
  const mainId = panelIds[0];

  const oIn = Array.isArray(payload.o) ? payload.o : [];
  const object = {
    name: oIn[4] != null ? String(oIn[4]) : "",
    property_type: fromIdx(PTYPE, Number(oIn[0]) || 0, "apartment"),
    floor_area_m2: Number(oIn[1]) || 60,
    floors: Math.max(1, Number(oIn[2]) || 1),
    stage: fromIdx(STAGE, Number(oIn[3]) || 0, "design"),
  };

  const expert = !!payload.x;
  let rooms = [];
  let systems = {
    heating: {
      panel_id: mainId,
      boiler: "none",
      collector_loops: 0,
      heating_pumps: 0,
      fan_coils: 0,
      heat_pump: 0,
      fireplace: 0,
      pt100_sensors: 0,
      ds18b20_sensors: 0,
    },
    ventilation: {
      panel_id: mainId,
      ahu: 0,
      recuperator: 0,
      extract_fans: 0,
      dampers_0_10v: 0,
      sensors_0_10v: 0,
      sensors_4_20ma: 0,
    },
    water: {
      panel_id: mainId,
      leak_zones: 0,
      shutoff_valves: 0,
      water_meters: 0,
      irrigation: 0,
      water_pumps: 0,
      dhw_recirc: 0,
      gas_valve: 0,
    },
    electrical: {
      panel_id: mainId,
      energy_phases: 0,
      load_shed: 0,
      ev_chargers: 0,
      pv_inverters: 0,
      fault_contacts: 0,
    },
    security: {
      panel_id: mainId,
      powered_sensors: [],
      dry_contacts: 0,
      gates: 0,
      locks: 0,
      panic_buttons: 0,
    },
    lighting_scenes: {
      panel_id: mainId,
      stair_steps: 0,
      accent_zones: 0,
      garden_lights: 0,
    },
    system: { manual_control: true, ha_server: "needed" },
  };

  if (!expert && Array.isArray(payload.r)) {
    rooms = payload.r.map((row) => {
      // Canonical: [template, name, panelIndex, sparse?]
      // Legacy links mistakenly used [panelId, template, name, sparse?]
      let template;
      let name;
      let pIdx;
      let sparse;
      const a0 = row[0];
      const a1 = row[1];
      const a2 = row[2];
      const a3 = row[3];
      const panelFirst =
        typeof a0 === "string" &&
        (panelIds.includes(a0) || /^panel-/i.test(a0)) &&
        typeof a1 === "string" &&
        typeof a2 === "string";
      if (panelFirst) {
        template = String(a1 || "living");
        name = String(a2 || "");
        pIdx = Math.max(0, panelIds.indexOf(String(a0)));
        sparse = a3 && typeof a3 === "object" ? a3 : {};
      } else {
        template = String(a0 || "living");
        name = String(a1 || "");
        pIdx = Number(a2) || 0;
        sparse = a3 && typeof a3 === "object" ? a3 : {};
      }
      const room = {
        template,
        name,
        panel_id: panelIds[pIdx] || mainId,
        lights_onoff: 0,
        lights_dimmable: 0,
        led_strips: 0,
        led_strip_channels: 4,
        led_single: 0,
        switches: 0,
        shutters: 0,
        ufh_loops: 0,
        ufh_electric: 0,
        lights_0_10v: 0,
        temp_sensor: "none",
        leak_sensors: 0,
        motion_sensors: 0,
        presence_sensors: 0,
        door_contacts: 0,
        smart_sockets: 0,
        extract_fan: 0,
        manual: sparse.m ? {} : {},
      };
      for (const [short, long, def] of ROOM_KEYS) {
        if (!Object.prototype.hasOwnProperty.call(sparse, short)) continue;
        if (long === "temp_sensor") {
          room.temp_sensor = fromIdx(TEMP, Number(sparse[short]) || 0, "none");
        } else {
          room[long] = typeof def === "number" ? Number(sparse[short]) || 0 : sparse[short];
        }
      }
      // Legacy typo: switches packed as "s" instead of "sw"
      if (sparse.s != null && room.switches === 0) {
        room.switches = Number(sparse.s) || 0;
      }
      return room;
    });
  }

  if (!expert && payload.y && typeof payload.y === "object") {
    for (const [short, long] of Object.entries(SYS_SECTIONS)) {
      const packed = payload.y[short];
      if (!packed) continue;
      unpackSparse(packed, SECTION_KEYS[long], systems[long]);
      if (long === "heating" && packed.b != null) {
        systems.heating.boiler = fromIdx(BOILER, Number(packed.b) || 0, "none");
      }
      if (long === "security" && Array.isArray(packed.ps)) {
        systems.security.powered_sensors = packed.ps.map((row) => ({
          type: String(row[0] || "pir"),
          qty: Number(row[1]) || 0,
        }));
      }
      if (packed.pi != null) {
        systems[long].panel_id = panelIds[Number(packed.pi)] || mainId;
      }
    }
    if (payload.y.g) {
      const g = payload.y.g;
      if (g.m === 0) systems.system.manual_control = false;
      if (g.h != null) systems.system.ha_server = fromIdx(HA, Number(g.h) || 0, "needed");
    }
  }

  const expertDemand =
    expert && payload.d && typeof payload.d === "object" ? payload.d : {};

  const ui_mode = payload.m === "s" ? "simple" : "advanced";

  return {
    ok: true,
    older: warn,
    patch: {
      ui_mode,
      step: ui_mode === "advanced" ? 3 : 0,
      expert: ui_mode === "simple" ? false : expert,
      object,
      panels,
      rooms,
      rooms_user_edited: true,
      systems,
      expertDemand,
      systems_expanded: null,
      shareFromLink: true,
      shareLinkOlder: warn,
    },
  };
}

function encodeShareLink(state) {
  const payload = buildSharePayload(state);
  const json = JSON.stringify(payload);
  return bytesToBase64Url(utf8Encode(json));
}

function decodeShareLink(token) {
  try {
    const json = utf8Decode(base64UrlToBytes(String(token || "").trim()));
    const payload = JSON.parse(json);
    return expandSharePayload(payload);
  } catch (err) {
    return { ok: false, older: false, patch: null, error: String(err?.message || err) };
  }
}

/** Full URL length for a page origin + path + ?c= */
function shareUrlLength(originPath, state) {
  const c = encodeShareLink(state);
  return `${originPath}?c=${c}`.length;
}

HM.buildSharePayload = buildSharePayload;
HM.expandSharePayload = expandSharePayload;
HM.encodeShareLink = encodeShareLink;
HM.decodeShareLink = decodeShareLink;
HM.shareUrlLength = shareUrlLength;
HM.SHARE_SCHEMA_VERSION = SHARE_SCHEMA_VERSION;

// ===== example-configs.js =====
/**
 * Shared Simple-mode example presets (Apartment / House / Villa).
 * Used by the configurator UI and the homepage embed — one code path for
 * estimate inputs, card prices, and ?c= share links.
 */




const EXAMPLE_CARDS = [
  ["apartment", "Apartment"],
  ["house", "Detached house"],
  ["villa", "Large villa"],
];

const DEFAULT_RULES_URL = "https://config.home-master.eu/estimator/rules.json";

/**
 * @param {string} [rulesUrl]
 */
function examplesAssetsBase(rulesUrl = DEFAULT_RULES_URL) {
  try {
    return new URL("./assets/examples/", String(rulesUrl).replace(/[^/]+$/, "")).href;
  } catch {
    return "https://config.home-master.eu/estimator/assets/examples/";
  }
}

/** @type {Promise<object>|null} */
let examplesManifestPromise = null;

/**
 * @param {string} [rulesUrl]
 * @returns {Promise<object>}
 */
function loadExamplesManifest(rulesUrl = DEFAULT_RULES_URL) {
  if (!examplesManifestPromise) {
    const url = new URL("manifest.json", examplesAssetsBase(rulesUrl)).href;
    examplesManifestPromise = fetch(url)
      .then((r) => {
        if (!r.ok) throw new Error(`examples manifest HTTP ${r.status}`);
        return r.json();
      })
      .catch((err) => {
        examplesManifestPromise = null;
        throw err;
      });
  }
  return examplesManifestPromise;
}

/**
 * @param {string} moduleId
 * @param {object|null} rules
 * @param {Record<string, {available?: boolean}>} priceMap
 */
function moduleIsAvailable(moduleId, rules, priceMap) {
  const spec = rules?.modules?.[moduleId];
  if (!spec?.sku) return true;
  const p = priceMap?.[spec.sku];
  if (!p) return true;
  return p.available !== false;
}

/**
 * Build the exact Simple example configuration used for card price AND share/apply.
 * Always starts from emptySystems — never merges leftover Advanced/Simple systems.
 *
 * @param {string} kind
 * @param {{ rules?: object|null, isAvailable?: (id: string) => boolean, stage?: string, panelId?: string }} opts
 */
function buildExampleConfig(kind, opts = {}) {
  const rules = opts.rules || null;
  const panelId = opts.panelId || "panel-1";
  const stage = opts.stage || "design";
  const isAvailable =
    typeof opts.isAvailable === "function" ? opts.isAvailable : () => true;

  const raw = simplePreset(kind === "villa" ? "villa" : kind === "house" ? "house" : "apartment");
  const { preset: p, exclusions, controllersOk } = adaptPresetForAvailability(raw, isAvailable);
  const { rooms, warnings } = applySimpleDistribution({
    counts: p.counts,
    totals: p.totals,
    rooms: [],
    roomTypeLabels: rules?.room_type_labels,
    roomTemplates: rules?.room_templates,
    roomDefaultsFn: (t) => simpleRoomDefaults(t),
    panelId,
  });
  let systems = applySimpleToggles(emptySystems(panelId), p.toggles);
  systems.heating.collector_loops = Math.max(0, Number(p.totals.ufh_loops) || 0);
  if (p.clearStairLighting && systems.lighting_scenes) {
    systems.lighting_scenes.stair_steps = 0;
    systems.lighting_scenes.accent_zones = 0;
  }
  const inputs = {
    panels: resolvePanels({ panels: [{ id: panelId, name: "Main panel", location: "" }] }),
    rooms,
    systems,
    stage,
    property_type: p.property_type,
    floor_area_m2: p.floor_area_m2,
    floors: p.floors,
  };
  return {
    kind: kind === "villa" ? "villa" : kind === "house" ? "house" : "apartment",
    preset: p,
    exclusions,
    controllersOk,
    rooms,
    systems,
    warnings,
    inputs,
  };
}

/**
 * Configurator-shaped state for encodeShareLink / applySharePatch.
 * @param {ReturnType<typeof buildExampleConfig>} cfg
 * @param {{ stage?: string }} [opts]
 */
function shareStateFromExampleConfig(cfg, opts = {}) {
  const stage = opts.stage || "design";
  return {
    ui_mode: "simple",
    step: 0,
    expert: false,
    object: {
      property_type: cfg.preset.property_type,
      floor_area_m2: cfg.preset.floor_area_m2,
      floors: cfg.preset.floors,
      stage,
      name: "",
      cabinets: 1,
    },
    panels: [{ id: "panel-1", name: "Main panel", location: "" }],
    rooms: cfg.rooms,
    rooms_user_edited: true,
    systems: cfg.systems,
    expertDemand: {},
    simple: {
      counts: cfg.preset.counts,
      totals: cfg.preset.totals,
      toggles: cfg.preset.toggles,
      preset: cfg.kind,
      controllersOk: cfg.controllersOk,
      warnings: cfg.warnings || [],
    },
  };
}

/**
 * @param {ReturnType<typeof buildExampleConfig>} cfg
 * @param {{ path?: string, stage?: string }} [opts]
 */
function exampleShareHref(cfg, opts = {}) {
  const path = opts.path || "/system-builder";
  const token = encodeShareLink(shareStateFromExampleConfig(cfg, { stage: opts.stage }));
  return `${path}?c=${token}`;
}

/**
 * Same label the configurator card shows.
 * @param {ReturnType<typeof buildExampleConfig>} cfg
 * @param {object} rules
 * @param {Record<string, {amount:number, currency:string, available?: boolean}>} priceMap
 * @returns {{ text: string, total: number|null, currency: string|null, result: object|null }}
 */
function exampleCardPrice(cfg, rules, priceMap) {
  if (!cfg?.controllersOk) {
    return { text: "unavailable", total: null, currency: null, result: null };
  }
  const result = estimate(cfg.inputs, rules, priceMap);
  const sys = systemTotal(result, priceMap);
  if (sys && sys.pricedQty > 0) {
    return {
      text: `${sys.total} ${sys.currency}`,
      total: sys.total,
      currency: sys.currency,
      result,
    };
  }
  return { text: "see estimate", total: null, currency: null, result };
}

/**
 * Shop URLs for every module in rules (stock catalog), same idea as configurator.
 * @param {object|null} rules
 * @returns {string[]}
 */
function allModuleShopUrls(rules) {
  const specs = rules?.modules || {};
  return [
    ...new Set(
      Object.values(specs)
        .map((s) => s?.shop_url)
        .filter(Boolean),
    ),
  ];
}

HM.examplesAssetsBase = examplesAssetsBase;
HM.loadExamplesManifest = loadExamplesManifest;
HM.moduleIsAvailable = moduleIsAvailable;
HM.buildExampleConfig = buildExampleConfig;
HM.shareStateFromExampleConfig = shareStateFromExampleConfig;
HM.exampleShareHref = exampleShareHref;
HM.exampleCardPrice = exampleCardPrice;
HM.allModuleShopUrls = allModuleShopUrls;
HM.EXAMPLE_CARDS = EXAMPLE_CARDS;

// ===== examples-embed.js =====
/**
 * Homepage embed: three Simple example cards → /system-builder?c=.
 * Reuses estimate / prices / share / example-configs — no second engine.
 */


const RULES_URL =
  (typeof globalThis !== "undefined" &&
    (globalThis.HM_ESTIMATOR_RULES_URL || globalThis.HM_RULES_URL)) ||
  "https://config.home-master.eu/estimator/rules.json";

/** Separate from configurator sessionStorage price cache. */
const CACHE_RULES_KEY = "hm_examples_rules_v1";
const CACHE_PRICES_KEY = "hm_examples_prices_v1";
const CACHE_TTL_MS = 24 * 60 * 60 * 1000;

const SYSTEM_BUILDER_PATH = "/system-builder";

function readCache(key) {
  try {
    if (typeof localStorage === "undefined") return null;
    const raw = localStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return null;
    if (!Number.isFinite(parsed.savedAt)) return null;
    if (Date.now() - parsed.savedAt > CACHE_TTL_MS) return null;
    return parsed.data ?? null;
  } catch {
    return null;
  }
}

function writeCache(key, data) {
  try {
    if (typeof localStorage === "undefined") return;
    localStorage.setItem(key, JSON.stringify({ savedAt: Date.now(), data }));
  } catch {
    /* quota / private mode */
  }
}

function ensureStyles() {
  if (typeof document === "undefined") return;
  if (document.querySelector('link[data-hm-examples-css="1"]')) return;
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.setAttribute("data-hm-examples-css", "1");
  try {
    link.href = new URL("./examples.css", import.meta.url).href;
  } catch {
    link.href = "https://config.home-master.eu/estimator/examples.css";
  }
  document.head.appendChild(link);
}

function escapeAttr(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

/**
 * Paint cards immediately (photos + titles). Prices and ?c= filled later.
 * @param {HTMLElement} root
 */
function renderExampleCardsShell(root) {
  root.innerHTML = `
    <div class="hm-home-examples__row">
      ${EXAMPLE_CARDS.map(
        ([id, label]) => `
        <a class="hm-home-examples__card" data-preset="${id}" href="${SYSTEM_BUILDER_PATH}">
          <span class="hm-home-examples__media">
            <img class="hm-home-examples__img" data-preset-img="${id}" alt="" width="600" height="335" decoding="async">
            <span class="hm-home-examples__caption">
              <strong>${escapeAttr(label)}</strong>
              <span class="hm-home-examples__price" data-preset-price="${id}"></span>
            </span>
          </span>
        </a>`,
      ).join("")}
    </div>`;
}

function applyManifestPhotos(root, manifest) {
  const base = examplesAssetsBase(RULES_URL);
  for (const [id] of EXAMPLE_CARDS) {
    const entry = manifest?.[id];
    const img = root.querySelector(`[data-preset-img="${id}"]`);
    if (!img || !entry?.file) continue;
    img.src = new URL(entry.file, base).href;
    img.alt = entry.alt || "";
  }
}

/**
 * @param {object} rules
 * @param {Record<string, object>} priceMap
 * @param {HTMLElement} root
 */
function fillCardsFromRules(root, rules, priceMap) {
  const isAvailable = (id) => moduleIsAvailable(id, rules, priceMap);
  for (const [kind] of EXAMPLE_CARDS) {
    const link = root.querySelector(`a[data-preset="${kind}"]`);
    const elPrice = root.querySelector(`[data-preset-price="${kind}"]`);
    try {
      const cfg = buildExampleConfig(kind, { rules, isAvailable });
      if (link) link.href = exampleShareHref(cfg, { path: SYSTEM_BUILDER_PATH });
      if (elPrice) {
        const priced = exampleCardPrice(cfg, rules, priceMap);
        elPrice.textContent =
          priced.total != null ? priced.text : priceMap && Object.keys(priceMap).length ? priced.text : "";
      }
    } catch (err) {
      console.warn("hm-examples:", kind, err);
      if (link) link.href = SYSTEM_BUILDER_PATH;
    }
  }
}

async function loadRulesCached() {
  const cached = readCache(CACHE_RULES_KEY);
  if (cached && typeof cached === "object" && cached.modules) return cached;
  const res = await fetch(RULES_URL);
  if (!res.ok) throw new Error(`rules ${res.status}`);
  const data = await res.json();
  writeCache(CACHE_RULES_KEY, data);
  return data;
}

/**
 * Use 24h localStorage; fetch only SKUs still missing.
 * @param {object} rules
 * @param {string[]} urls
 */
async function ensureExamplePrices(rules, urls) {
  const cached = readCache(CACHE_PRICES_KEY);
  let priceMap = cached && typeof cached === "object" ? { ...cached } : {};

  const specs = Object.values(rules?.modules || {});
  const skuByUrl = new Map(
    specs.filter((s) => s?.shop_url && s?.sku).map((s) => [s.shop_url, s.sku]),
  );
  const missingUrls = urls.filter((u) => {
    const sku = skuByUrl.get(u);
    if (!sku) return true;
    const p = priceMap[sku];
    return !(p && Number.isFinite(p.amount));
  });

  if (missingUrls.length) {
    try {
      const map = await fetchPrices(missingUrls, { preferredCurrency: detectShopCurrency() });
      priceMap = { ...priceMap, ...toEstimatePriceMap(map) };
      writeCache(CACHE_PRICES_KEY, priceMap);
    } catch (err) {
      console.warn("hm-examples prices:", err);
    }
  }
  return priceMap;
}

/**
 * @param {HTMLElement} [root]
 */
async function mountExamples(root) {
  const el =
    root ||
    (typeof document !== "undefined" ? document.getElementById("hm-examples") : null);
  if (!el) return;

  ensureStyles();
  renderExampleCardsShell(el);

  loadExamplesManifest(RULES_URL)
    .then((manifest) => applyManifestPhotos(el, manifest))
    .catch((err) => console.warn("hm-examples manifest:", err));

  let rules = null;
  try {
    rules = await loadRulesCached();
  } catch (err) {
    console.warn("hm-examples rules:", err);
    return;
  }

  // First pass: links without stock gate (or with cached prices).
  let priceMap = readCache(CACHE_PRICES_KEY) || {};
  fillCardsFromRules(el, rules, priceMap);

  try {
    const urls = allModuleShopUrls(rules);
    priceMap = await ensureExamplePrices(rules, urls);
    // Re-adapt with availability, then price BOM lines (may need module URLs from estimate).
    fillCardsFromRules(el, rules, priceMap);
    for (const [kind] of EXAMPLE_CARDS) {
      const cfg = buildExampleConfig(kind, {
        rules,
        isAvailable: (id) => moduleIsAvailable(id, rules, priceMap),
      });
      const priced = exampleCardPrice(cfg, rules, priceMap);
      const bomUrls = (priced.result?.modules || []).map((m) => m.shop_url).filter(Boolean);
      if (bomUrls.length) {
        priceMap = await ensureExamplePrices(rules, bomUrls);
      }
    }
    fillCardsFromRules(el, rules, priceMap);
  } catch (err) {
    console.warn("hm-examples:", err);
  }
}

function autoMount() {
  if (typeof document === "undefined") return;
  const boot = () => {
    const el = document.getElementById("hm-examples");
    if (el) mountExamples(el);
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
}

autoMount();


HM.renderExampleCardsShell = renderExampleCardsShell;
HM.mountExamples = mountExamples;
HM.CACHE_RULES_KEY = CACHE_RULES_KEY;
HM.CACHE_PRICES_KEY = CACHE_PRICES_KEY;
HM.CACHE_TTL_MS = CACHE_TTL_MS;


export { estimate, fetchPrices, encodeShareLink, decodeShareLink, buildExampleConfig, exampleCardPrice, exampleShareHref, mountExamples };
